// ----- 8< ----- FILE "./SysClockGen.v" ----- 8< -----

module SysClockGen(
    input wire clk0, // standard digital clk, default
    input wire clk1, // analog clk
    input wire sel,
    output clock_sys
);
    // Sync sel to ~clk0
    reg           sel_0p, sel_0n;
    reg           sel_1p, sel_1n;
    always @(posedge clk0)
        sel_0p <= (~sel); //  Tarkovsky Change as can be force back to CLK0. | Before: sel_0p <= (~sel) & (~sel_1n);
                        //  This change is due to CLK0 usually is slower than CLK1.
                        //  And if CLK1 is off, the MUX can be switch back to CLK0.

    always @(negedge clk0)
        sel_0n <= sel_0p;

    // Sync sel_0n to ~clk1
    always @(posedge clk1)
        sel_1p <= sel & (~sel_0n);

    always @(negedge clk1)
        sel_1n <= sel_1p;

    // Final mux
    wire          sel1 = sel_1n;
    wire          sel0 = sel_0n;

    //assign        clk = (sel1 & clk1) | (sel0 & clk0);
    wire          clk_sel0;
    wire          clk_sel1;

`ifdef FLOW_ASIC
    CKLNQD8BWP6T20P96CPD i_clkgate_u0 (.TE(1'b0), .E(sel0), .CP(clk0), .Q(clk_sel0));
    CKLNQD8BWP6T20P96CPD i_clkgate_u1 (.TE(1'b0), .E(sel1), .CP(clk1), .Q(clk_sel1));
    CKOR2D8BWP6T20P96CPD i_clkor2_dontouch(.A1(clk_sel0), .A2(clk_sel1), .Z(clock_sys));
`else
    reg clk_gate0, clk_gate1;
    always @(*)
        if (!clk0)        
            clk_gate0 = sel0;
    always @(*)
        if (!clk1)        
            clk_gate1 = sel1;
    assign clk_sel0 = clk_gate0 & clk0;
    assign clk_sel1 = clk_gate1 & clk1;
